Service design:

```java
@Service
public class RegulatedTransferService {
    static final String OP_INITIATE = "REG_TRANSFER_INITIATE";
    static final String OP_CHECKIN = "REG_TRANSFER_CHECKIN";
    static final String OP_ACCEPT = "REG_TRANSFER_ACCEPT";
    static final String OP_CANCEL = "REG_TRANSFER_CANCEL";

    // repos: EvidenceRepository, RegulatedTransferRepository, RegulatedCheckpointRepository,
    //        RegulatedCheckinRepository, RegulatedExceptionRepository, CommandLogRepository,
    //        ObjectMapper, EvidenceClock

    @Transactional
    public StoredResponse initiate(String actorId, String evidenceKey, RegulatedTransferInitiateRequest request, String requestHash) {
        Evidence evidence = lockEvidence(evidenceKey);
        // 权限先于重放
        if (!evidence.custodianId().equals(actorId)) throw forbidden;
        Optional<StoredResponse> replay = checkReplay(request.requestId(), requestHash);
        if (replay.isPresent()) return replay.get();
        // replay again after lock? We already hold the lock since lockEvidence first. Order: lock → permission → replay → business. Good, single replay check suffices since lock held.
        if (request.toCustodian().equals(actorId)) badRequest;
        if (evidence.status() == SEAL_BROKEN) unprocessable;
        if (evidence.status() == TRANSFER_PENDING) conflict("已存在在途交接");
        if (evidence.status() == BORROWED) conflict("借出期间禁止发起交接");
        // deadlines strictly increasing and in future
        LocalDateTime nowUtc = clock.nowUtc();
        LocalDateTime prev = nowUtc;
        for spec : request.checkpoints():
            if (!spec.deadlineAt().isAfter(prev)) throw badRequest("截止时刻须严格递增且晚于当前时刻");
            prev = spec.deadlineAt();
        String transferKey = "RT-" + UUID random (12 hex?) — must be ≤64. Use UUID without dashes substring? Full UUID 36 chars fits. "RT-" + UUID.randomUUID() = 39 chars. OK.
        transferRepository.insert(...);
        for i,spec: checkpointRepository.insert(transferKey, i+1, spec.deadlineAt());
